/**
 * Kong plugin schemas, generated by scripts/codegen-plugins.ts: Kong's own JSON
 * Schemas (vendored, embedded unchanged) and zod schemas generated from them
 * at build time by @hey-api/openapi-ts.
 */
import type { z } from "zod";
import { PLUGIN_JSON, PLUGIN_ZOD } from "./generated/plugins/index.js";

export type PluginName = keyof typeof PLUGIN_JSON;
export type JSONSchema = z.core.JSONSchema.JSONSchema;

export const PLUGIN_NAMES = Object.keys(PLUGIN_JSON) as PluginName[];

export function isPluginName(name: string): name is PluginName {
  return Object.hasOwn(PLUGIN_JSON, name);
}

/**
 * Kong's JSON Schema for a plugin, unchanged (served at /schemas/plugins/{name}).
 * The object is shared by the whole isolate: clone it before changing it.
 */
export function jsonSchema(name: PluginName): JSONSchema {
  return PLUGIN_JSON[name] as JSONSchema;
}

/** zod schema for a plugin entity (`{ config, protocols, ... }`), generated from Kong's JSON Schema. */
export function kongSchema<N extends PluginName>(
  name: N,
): (typeof PLUGIN_ZOD)[N] {
  return PLUGIN_ZOD[name];
}

export * as tables from "./db/tables.js";
export { ENTITY_NAMES, type EntityName, entitySchemas } from "./db/zod.js";
